@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=Inter:wght@300;400;500;600&display=swap');

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --primary: #1a0a6b;
  --primary-light: #2d1b9e;
  --accent: #E6FF32;
  --accent-dark: #c8e000;
  --coral: #FF5C5C;
  --coral-dark: #e04444;
  --white: #ffffff;
  --off-white: #f9f8ff;
  --gray-50: #f8fafc;
  --gray-100: #f1f5f9;
  --gray-200: #e2e8f0;
  --gray-300: #cbd5e1;
  --gray-400: #94a3b8;
  --gray-500: #64748b;
  --gray-700: #334155;
  --gray-900: #0f172a;
  --shadow-sm: 0 1px 3px rgba(0,0,0,.08);
  --shadow-md: 0 4px 16px rgba(0,0,0,.1);
  --shadow-lg: 0 8px 32px rgba(0,0,0,.14);
  --shadow-xl: 0 16px 48px rgba(0,0,0,.18);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-xl: 28px;
  --font-heading: 'Plus Jakarta Sans', sans-serif;
  --font-body: 'Inter', sans-serif;
  --transition: 200ms ease;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  color: var(--gray-900);
  background: var(--white);
  line-height: 1.6;
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
}

h1,h2,h3,h4,h5,h6 {
  font-family: var(--font-heading);
  line-height: 1.2;
  font-weight: 700;
}

a { text-decoration: none; color: inherit; }
img { max-width: 100%; height: auto; display: block; }

/* ─── NAV ─── */
.nav {
  position: sticky; top: 0; z-index: 100;
  background: rgba(255,255,255,.96);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
  padding: 0 24px;
  height: 68px;
  display: flex; align-items: center;
}
.nav-inner {
  max-width: 1200px; margin: 0 auto; width: 100%;
  display: flex; align-items: center; gap: 32px;
}
.nav-logo {
  font-family: var(--font-heading);
  font-weight: 800; font-size: 22px;
  color: var(--primary);
  display: flex; align-items: center; gap: 8px;
  flex-shrink: 0;
}
.nav-logo-icon {
  width: 32px; height: 32px;
  background: var(--primary);
  border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
}
.nav-logo-icon svg { color: var(--accent); }
.nav-links {
  display: flex; align-items: center; gap: 4px;
  list-style: none; flex: 1;
}
.nav-links a {
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  font-size: 15px; font-weight: 500;
  color: var(--gray-700);
  transition: background var(--transition), color var(--transition);
  cursor: pointer;
}
.nav-links a:hover,
.nav-links a.active {
  background: var(--gray-100);
  color: var(--primary);
}
.nav-cta {
  margin-left: auto;
  background: var(--primary);
  color: var(--accent) !important;
  padding: 10px 20px !important;
  border-radius: var(--radius-sm) !important;
  font-weight: 600 !important;
  font-size: 14px !important;
  transition: background var(--transition), transform var(--transition) !important;
}
.nav-cta:hover { background: var(--primary-light) !important; transform: translateY(-1px); }

/* Mobile nav */
.nav-hamburger {
  display: none; flex-direction: column; gap: 5px;
  background: none; border: none; cursor: pointer; padding: 8px;
  margin-left: auto;
}
.nav-hamburger span {
  width: 22px; height: 2px; background: var(--gray-700);
  border-radius: 2px; transition: var(--transition);
}
.nav-mobile {
  display: none; position: fixed; inset: 68px 0 0 0;
  background: var(--white); z-index: 99; padding: 24px;
  flex-direction: column; gap: 8px; overflow-y: auto;
}
.nav-mobile.open { display: flex; }
.nav-mobile a {
  padding: 14px 16px; border-radius: var(--radius-md);
  font-size: 16px; font-weight: 500; color: var(--gray-700);
  transition: background var(--transition);
}
.nav-mobile a:hover { background: var(--gray-100); color: var(--primary); }
.nav-mobile .nav-cta-mobile {
  margin-top: 8px; text-align: center;
  background: var(--primary); color: var(--accent);
  border-radius: var(--radius-md); padding: 16px;
  font-weight: 700; font-size: 16px;
}

/* ─── BUTTONS ─── */
.btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 14px 28px; border-radius: var(--radius-md);
  font-family: var(--font-heading); font-weight: 700;
  font-size: 15px; cursor: pointer; border: none;
  transition: all var(--transition); text-decoration: none;
}
.btn-primary {
  background: var(--accent);
  color: var(--primary);
}
.btn-primary:hover { background: var(--accent-dark); transform: translateY(-2px); box-shadow: 0 8px 24px rgba(230,255,50,.4); }
.btn-secondary {
  background: transparent;
  color: var(--white);
  border: 2px solid rgba(255,255,255,.4);
}
.btn-secondary:hover { border-color: var(--white); background: rgba(255,255,255,.1); }
.btn-dark {
  background: var(--primary);
  color: var(--accent);
}
.btn-dark:hover { background: var(--primary-light); transform: translateY(-2px); }
.btn-outline {
  background: transparent;
  color: var(--primary);
  border: 2px solid var(--gray-200);
}
.btn-outline:hover { border-color: var(--primary); }
.btn-sm { padding: 10px 20px; font-size: 14px; }
.btn-lg { padding: 18px 36px; font-size: 17px; }

/* ─── SECTIONS ─── */
.section { padding: 96px 24px; }
.section-sm { padding: 64px 24px; }
.container { max-width: 1200px; margin: 0 auto; }
.section-label {
  display: inline-block;
  background: rgba(26,10,107,.08);
  color: var(--primary);
  font-size: 13px; font-weight: 700;
  letter-spacing: .08em; text-transform: uppercase;
  padding: 6px 14px; border-radius: 100px;
  margin-bottom: 16px;
}
.section-title {
  font-size: clamp(28px, 4vw, 48px);
  font-weight: 800; color: var(--gray-900);
  line-height: 1.15;
  margin-bottom: 16px;
}
.section-subtitle {
  font-size: 18px; color: var(--gray-500);
  max-width: 560px; line-height: 1.65;
  margin-bottom: 40px;
}
.text-center { text-align: center; }
.text-center .section-subtitle { margin-left: auto; margin-right: auto; }

/* ─── HERO ─── */
.hero {
  background: var(--primary);
  padding: 80px 24px 0;
  overflow: hidden;
  position: relative;
}
.hero::before {
  content: '';
  position: absolute; inset: 0;
  background: radial-gradient(ellipse 80% 60% at 60% 0%, rgba(230,255,50,.12) 0%, transparent 60%);
  pointer-events: none;
}
.hero-inner {
  max-width: 1200px; margin: 0 auto;
  display: grid; grid-template-columns: 1fr 1fr;
  gap: 60px; align-items: center;
  padding-bottom: 80px;
}
.hero-content { position: relative; z-index: 1; }
.hero-badge {
  display: inline-flex; align-items: center; gap: 8px;
  background: rgba(230,255,50,.15);
  border: 1px solid rgba(230,255,50,.3);
  border-radius: 100px; padding: 6px 16px;
  margin-bottom: 24px;
}
.hero-badge span {
  font-size: 13px; font-weight: 600;
  color: var(--accent);
}
.hero-title {
  font-size: clamp(32px, 4.5vw, 56px);
  font-weight: 800; color: var(--white);
  line-height: 1.1; margin-bottom: 20px;
}
.hero-title .accent { color: var(--accent); }
.hero-subtitle {
  font-size: 18px; color: rgba(255,255,255,.75);
  line-height: 1.65; margin-bottom: 36px;
  max-width: 480px;
}
.hero-actions {
  display: flex; gap: 16px; flex-wrap: wrap;
  margin-bottom: 40px;
}
.hero-trust {
  display: flex; gap: 24px; flex-wrap: wrap;
}
.hero-trust-item {
  display: flex; align-items: center; gap: 8px;
  font-size: 14px; color: rgba(255,255,255,.6);
}
.hero-trust-item svg { color: var(--accent); flex-shrink: 0; }

/* Hero tab panel */
.hero-visual { position: relative; z-index: 1; }
.hero-tabs {
  display: flex; gap: 4px;
  background: rgba(255,255,255,.08);
  border-radius: 12px; padding: 4px;
  width: fit-content; margin-bottom: 20px;
}
.hero-tab {
  padding: 10px 20px; border-radius: 9px;
  font-size: 14px; font-weight: 600;
  color: rgba(255,255,255,.6);
  cursor: pointer; border: none; background: none;
  transition: all var(--transition);
}
.hero-tab.active {
  background: var(--accent);
  color: var(--primary);
}
.hero-screen {
  border-radius: 16px; overflow: hidden;
  box-shadow: 0 24px 64px rgba(0,0,0,.4);
  background: var(--white);
  display: none;
}
.hero-screen.active { display: block; }
.hero-screen-header {
  background: var(--gray-100);
  padding: 12px 16px;
  display: flex; align-items: center; gap: 8px;
  border-bottom: 1px solid var(--gray-200);
}
.hero-screen-dot {
  width: 10px; height: 10px; border-radius: 50%;
}
.hero-screen-body { padding: 24px; }

/* ─── STATS BAR ─── */
.stats-bar {
  background: var(--accent);
  padding: 32px 24px;
}
.stats-bar-inner {
  max-width: 1200px; margin: 0 auto;
  display: flex; justify-content: center;
  gap: 64px; flex-wrap: wrap;
}
.stat-item { text-align: center; }
.stat-number {
  font-family: var(--font-heading);
  font-size: clamp(28px, 4vw, 42px);
  font-weight: 800; color: var(--primary);
  line-height: 1;
  margin-bottom: 4px;
}
.stat-label {
  font-size: 14px; font-weight: 600;
  color: rgba(26,10,107,.65);
  text-transform: uppercase; letter-spacing: .06em;
}

/* ─── PRODUCT CARDS ─── */
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 24px; margin-top: 48px;
}
.product-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-xl);
  padding: 32px;
  transition: all 250ms ease;
  cursor: pointer;
}
.product-card:hover {
  border-color: var(--primary);
  box-shadow: var(--shadow-xl);
  transform: translateY(-4px);
}
.product-icon {
  width: 52px; height: 52px;
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 20px;
}
.product-card h3 {
  font-size: 20px; font-weight: 700;
  margin-bottom: 10px; color: var(--gray-900);
}
.product-card p { font-size: 15px; color: var(--gray-500); line-height: 1.6; }
.product-card-link {
  display: inline-flex; align-items: center; gap: 6px;
  margin-top: 20px;
  font-size: 14px; font-weight: 600; color: var(--primary);
}
.product-card-link:hover { gap: 10px; }
.product-card-link svg { transition: transform var(--transition); }
.product-card:hover .product-card-link svg { transform: translateX(4px); }

/* ─── WHY CHOOSE US TABS ─── */
.why-section { background: var(--gray-50); }
.why-tabs {
  display: flex; gap: 8px; flex-wrap: wrap;
  margin-bottom: 40px;
}
.why-tab {
  padding: 12px 20px; border-radius: 100px;
  font-size: 14px; font-weight: 600;
  color: var(--gray-500);
  cursor: pointer; border: 2px solid var(--gray-200);
  background: var(--white);
  transition: all var(--transition);
}
.why-tab.active {
  background: var(--primary);
  border-color: var(--primary);
  color: var(--accent);
}
.why-tab:hover:not(.active) { border-color: var(--primary); color: var(--primary); }
.why-content { display: none; }
.why-content.active {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px; align-items: center;
}
.why-features { list-style: none; display: flex; flex-direction: column; gap: 16px; }
.why-feature {
  display: flex; align-items: flex-start; gap: 14px;
  padding: 18px; background: var(--white);
  border-radius: var(--radius-md);
  border: 1px solid var(--gray-200);
  transition: box-shadow var(--transition);
}
.why-feature:hover { box-shadow: var(--shadow-md); }
.why-feature-icon {
  width: 36px; height: 36px; flex-shrink: 0;
  background: rgba(26,10,107,.08);
  border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
}
.why-feature-text strong { display: block; font-size: 15px; font-weight: 600; color: var(--gray-900); }
.why-feature-text span { font-size: 14px; color: var(--gray-500); }
.why-visual {
  background: var(--primary);
  border-radius: var(--radius-xl);
  padding: 40px;
  min-height: 320px;
  display: flex; flex-direction: column; justify-content: center;
  position: relative; overflow: hidden;
}
.why-visual::before {
  content: '';
  position: absolute; top: -60px; right: -60px;
  width: 200px; height: 200px;
  background: rgba(230,255,50,.1);
  border-radius: 50%;
}
.why-visual-stat {
  font-family: var(--font-heading);
  font-size: 56px; font-weight: 800;
  color: var(--accent); line-height: 1;
  margin-bottom: 8px;
}
.why-visual p { color: rgba(255,255,255,.75); font-size: 18px; }

/* ─── FEATURES (3-col) ─── */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 32px; margin-top: 48px;
}
.feature-card {
  padding: 32px;
  background: var(--white);
  border-radius: var(--radius-xl);
  border: 1px solid var(--gray-200);
  transition: all 250ms ease;
}
.feature-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-3px); }
.feature-icon {
  width: 52px; height: 52px;
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 20px;
}
.feature-card h3 { font-size: 20px; font-weight: 700; margin-bottom: 10px; }
.feature-card p { font-size: 15px; color: var(--gray-500); line-height: 1.65; }

/* ─── TESTIMONIALS CAROUSEL ─── */
.testimonials-section { background: var(--primary); padding: 96px 24px; }
.testimonials-section .section-title { color: var(--white); }
.testimonials-section .section-subtitle { color: rgba(255,255,255,.65); }
.testimonials-section .section-label { background: rgba(230,255,50,.15); color: var(--accent); }
.carousel-wrapper { position: relative; overflow: hidden; margin-top: 48px; }
.carousel-track {
  display: flex; gap: 24px;
  transition: transform 350ms ease;
}
.testimonial-card {
  flex: 0 0 calc(33.333% - 16px);
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: var(--radius-xl);
  padding: 32px;
}
.testimonial-quote {
  font-size: 16px; line-height: 1.7;
  color: rgba(255,255,255,.85);
  margin-bottom: 24px;
}
.testimonial-quote::before { content: '"'; font-size: 28px; color: var(--accent); line-height: 0; position: relative; top: 6px; margin-right: 4px; }
.testimonial-author { display: flex; align-items: center; gap: 14px; }
.testimonial-avatar {
  width: 44px; height: 44px; border-radius: 50%;
  background: var(--accent);
  display: flex; align-items: center; justify-content: center;
  font-family: var(--font-heading);
  font-weight: 700; font-size: 16px; color: var(--primary);
  flex-shrink: 0;
}
.testimonial-name { font-weight: 600; color: var(--white); font-size: 15px; }
.testimonial-role { font-size: 13px; color: rgba(255,255,255,.5); }
.testimonial-tag {
  display: inline-block;
  background: rgba(230,255,50,.15);
  color: var(--accent);
  font-size: 12px; font-weight: 600;
  padding: 4px 10px; border-radius: 100px;
  margin-bottom: 16px;
}
.carousel-controls {
  display: flex; justify-content: center; align-items: center;
  gap: 16px; margin-top: 32px;
}
.carousel-btn {
  width: 44px; height: 44px;
  border-radius: 50%; border: 2px solid rgba(255,255,255,.25);
  background: none; cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  color: var(--white);
  transition: all var(--transition);
}
.carousel-btn:hover { border-color: var(--accent); color: var(--accent); }
.carousel-dots { display: flex; gap: 8px; }
.carousel-dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: rgba(255,255,255,.3);
  cursor: pointer; border: none;
  transition: all var(--transition);
}
.carousel-dot.active { background: var(--accent); width: 24px; border-radius: 4px; }

/* ─── PRICING ─── */
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 24px; margin-top: 48px;
}
.pricing-card {
  background: var(--white);
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-xl);
  padding: 32px;
  transition: all 250ms ease;
  position: relative;
}
.pricing-card.featured {
  border-color: var(--primary);
  background: var(--primary);
  color: var(--white);
}
.pricing-badge {
  position: absolute; top: -14px; left: 50%; transform: translateX(-50%);
  background: var(--accent);
  color: var(--primary);
  font-size: 12px; font-weight: 700;
  padding: 4px 16px; border-radius: 100px;
  white-space: nowrap;
}
.pricing-name {
  font-size: 14px; font-weight: 700; text-transform: uppercase;
  letter-spacing: .08em; color: var(--gray-500);
  margin-bottom: 12px;
}
.pricing-card.featured .pricing-name { color: rgba(255,255,255,.6); }
.pricing-price {
  font-family: var(--font-heading);
  font-size: 36px; font-weight: 800;
  color: var(--gray-900); line-height: 1;
  margin-bottom: 4px;
}
.pricing-card.featured .pricing-price { color: var(--accent); }
.pricing-period { font-size: 14px; color: var(--gray-400); margin-bottom: 24px; }
.pricing-card.featured .pricing-period { color: rgba(255,255,255,.5); }
.pricing-features { list-style: none; display: flex; flex-direction: column; gap: 10px; margin-bottom: 28px; }
.pricing-features li {
  display: flex; align-items: flex-start; gap: 10px;
  font-size: 14px; color: var(--gray-700);
}
.pricing-card.featured .pricing-features li { color: rgba(255,255,255,.8); }
.pricing-features li svg { flex-shrink: 0; color: var(--primary); margin-top: 1px; }
.pricing-card.featured .pricing-features li svg { color: var(--accent); }

/* ─── INTEGRATIONS ─── */
.integrations-grid {
  display: flex; flex-wrap: wrap;
  gap: 16px; justify-content: center;
  margin-top: 48px;
}
.integration-chip {
  display: flex; align-items: center; gap: 10px;
  padding: 12px 20px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  font-size: 15px; font-weight: 600;
  color: var(--gray-700);
  transition: all var(--transition);
}
.integration-chip:hover {
  border-color: var(--primary);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}
.integration-chip-dot {
  width: 28px; height: 28px; border-radius: 6px;
  display: flex; align-items: center; justify-content: center;
  font-size: 13px; font-weight: 800;
}

/* ─── FAQ ─── */
.faq-list { max-width: 720px; margin: 48px auto 0; display: flex; flex-direction: column; gap: 8px; }
.faq-item {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: box-shadow var(--transition);
}
.faq-item:hover { box-shadow: var(--shadow-sm); }
.faq-question {
  width: 100%; text-align: left;
  padding: 20px 24px;
  display: flex; justify-content: space-between; align-items: center;
  gap: 16px;
  font-size: 16px; font-weight: 600; color: var(--gray-900);
  background: none; border: none; cursor: pointer;
  font-family: var(--font-body);
  transition: color var(--transition);
}
.faq-question:hover { color: var(--primary); }
.faq-icon {
  width: 28px; height: 28px; flex-shrink: 0;
  background: var(--gray-100);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  transition: background var(--transition), transform var(--transition);
}
.faq-item.open .faq-icon {
  background: var(--primary);
  transform: rotate(45deg);
}
.faq-item.open .faq-icon svg { color: var(--accent); }
.faq-answer {
  max-height: 0; overflow: hidden;
  transition: max-height 300ms ease, padding 300ms ease;
  padding: 0 24px;
  font-size: 15px; color: var(--gray-500); line-height: 1.7;
}
.faq-item.open .faq-answer {
  max-height: 300px;
  padding-bottom: 20px;
}

/* ─── CTA BANNER ─── */
.cta-banner {
  background: var(--primary); padding: 80px 24px;
  text-align: center;
  position: relative; overflow: hidden;
}
.cta-banner::before {
  content: '';
  position: absolute; inset: 0;
  background: radial-gradient(ellipse 60% 80% at 50% 0%, rgba(230,255,50,.15) 0%, transparent 60%);
  pointer-events: none;
}
.cta-banner-inner { position: relative; z-index: 1; }
.cta-banner h2 {
  font-size: clamp(28px, 4vw, 44px);
  font-weight: 800; color: var(--white);
  margin-bottom: 16px;
}
.cta-banner p { font-size: 18px; color: rgba(255,255,255,.7); margin-bottom: 36px; }
.cta-banner-actions { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* ─── GLOBAL SCALE ─── */
.global-section {
  background: linear-gradient(135deg, var(--primary) 0%, #2d1b9e 100%);
  padding: 96px 24px;
  text-align: center;
}
.global-section .section-title { color: var(--white); }
.global-section .section-subtitle { color: rgba(255,255,255,.7); }
.global-section .section-label { background: rgba(230,255,50,.15); color: var(--accent); }
.globe-visual {
  width: 280px; height: 280px; margin: 48px auto;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, rgba(230,255,50,.25) 0%, rgba(26,10,107,0) 60%),
              radial-gradient(circle at 65% 65%, rgba(255,255,255,.06) 0%, rgba(26,10,107,0) 50%);
  border: 2px solid rgba(230,255,50,.3);
  display: flex; align-items: center; justify-content: center;
  position: relative;
}
.globe-inner {
  font-family: var(--font-heading);
  font-size: 28px; font-weight: 800;
  color: var(--accent); text-align: center;
}
.globe-inner span { display: block; font-size: 14px; font-weight: 500; color: rgba(255,255,255,.6); }

/* ─── AI SECTION ─── */
.ai-section { background: var(--off-white); }
.ai-grid {
  display: grid; grid-template-columns: 1fr 1fr;
  gap: 64px; align-items: center; margin-top: 48px;
}
.ai-features { display: flex; flex-direction: column; gap: 20px; }
.ai-feature-item {
  display: flex; gap: 16px; align-items: flex-start;
  padding: 20px;
  background: var(--white);
  border-radius: var(--radius-md);
  border: 1px solid var(--gray-200);
}
.ai-feature-icon {
  width: 40px; height: 40px; flex-shrink: 0;
  background: linear-gradient(135deg, var(--primary), #5b3ff0);
  border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
}
.ai-feature-item h4 { font-size: 16px; font-weight: 700; margin-bottom: 4px; }
.ai-feature-item p { font-size: 14px; color: var(--gray-500); }
.ai-visual {
  background: var(--primary);
  border-radius: var(--radius-xl);
  padding: 32px;
  position: relative;
}
.ai-prompt-box {
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.15);
  border-radius: var(--radius-md);
  padding: 20px;
  margin-bottom: 16px;
}
.ai-prompt-label { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: .1em; color: var(--accent); margin-bottom: 8px; }
.ai-prompt-text { font-size: 14px; color: rgba(255,255,255,.75); line-height: 1.6; }
.ai-badge {
  display: inline-flex; align-items: center; gap: 6px;
  background: var(--accent); color: var(--primary);
  font-size: 12px; font-weight: 700;
  padding: 4px 12px; border-radius: 100px;
}

/* ─── TOOLS GRID ─── */
.tools-grid-section { background: var(--gray-50); }
.tools-categories { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 24px; margin-top: 48px; }
.tool-category {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 24px;
  border: 1px solid var(--gray-200);
}
.tool-category-header {
  display: flex; align-items: center; gap: 10px;
  margin-bottom: 16px;
}
.tool-category-icon {
  width: 36px; height: 36px; border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
}
.tool-category h4 { font-size: 16px; font-weight: 700; }
.tool-list { list-style: none; display: flex; flex-direction: column; gap: 8px; }
.tool-list li { font-size: 14px; color: var(--gray-500); display: flex; align-items: center; gap: 6px; }
.tool-list li::before { content: ''; width: 5px; height: 5px; border-radius: 50%; background: var(--primary); opacity: .5; flex-shrink: 0; }

/* ─── SOCIAL PROOF BAR ─── */
.social-proof {
  background: var(--gray-50); padding: 64px 24px;
  border-top: 1px solid var(--gray-200);
  border-bottom: 1px solid var(--gray-200);
}
.social-proof-inner {
  max-width: 1200px; margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between;
  gap: 32px; flex-wrap: wrap;
}
.social-proof-text h3 { font-size: 24px; font-weight: 700; margin-bottom: 8px; }
.social-proof-text p { color: var(--gray-500); }
.stars { display: flex; gap: 4px; margin-bottom: 8px; }
.star { color: #fbbf24; }

/* ─── 3 STEPS ─── */
.steps-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 32px; margin-top: 48px;
}
.step-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: 32px;
  border: 1px solid var(--gray-200);
  position: relative;
}
.step-number {
  font-family: var(--font-heading);
  font-size: 72px; font-weight: 800;
  color: var(--gray-100);
  line-height: 1;
  margin-bottom: 16px;
  transition: color var(--transition);
}
.step-card:hover .step-number { color: rgba(26,10,107,.08); }
.step-card h3 { font-size: 20px; font-weight: 700; margin-bottom: 10px; }
.step-card p { font-size: 15px; color: var(--gray-500); line-height: 1.65; }

/* ─── RESOURCES ─── */
.resources-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 24px; margin-top: 48px; }
.resource-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all 250ms ease;
}
.resource-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-3px); }
.resource-card-img {
  height: 160px;
  display: flex; align-items: center; justify-content: center;
  font-size: 36px;
}
.resource-card-body { padding: 24px; }
.resource-card-tag {
  font-size: 12px; font-weight: 700; text-transform: uppercase;
  letter-spacing: .08em; color: var(--primary);
  margin-bottom: 10px;
}
.resource-card h4 { font-size: 17px; font-weight: 700; color: var(--gray-900); line-height: 1.4; margin-bottom: 8px; }
.resource-card p { font-size: 14px; color: var(--gray-500); }

/* ─── FOOTER ─── */
.footer {
  background: var(--gray-900);
  padding: 64px 24px 32px;
  color: rgba(255,255,255,.6);
}
.footer-inner {
  max-width: 1200px; margin: 0 auto;
}
.footer-top {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 48px;
  padding-bottom: 48px;
  border-bottom: 1px solid rgba(255,255,255,.1);
  margin-bottom: 32px;
}
.footer-brand .nav-logo { color: var(--white); margin-bottom: 16px; }
.footer-brand p { font-size: 14px; line-height: 1.7; max-width: 260px; }
.footer-col h5 {
  font-family: var(--font-heading);
  font-size: 14px; font-weight: 700;
  color: var(--white); text-transform: uppercase;
  letter-spacing: .08em; margin-bottom: 16px;
}
.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.footer-col ul a {
  font-size: 14px; color: rgba(255,255,255,.55);
  transition: color var(--transition);
}
.footer-col ul a:hover { color: var(--accent); }
.footer-bottom {
  display: flex; justify-content: space-between; align-items: center;
  flex-wrap: wrap; gap: 16px;
}
.footer-bottom p { font-size: 13px; }
.footer-bottom-links { display: flex; gap: 24px; }
.footer-bottom-links a { font-size: 13px; color: rgba(255,255,255,.4); }
.footer-bottom-links a:hover { color: var(--accent); }

/* ─── HERO VISUAL MOCK ─── */
.mock-dashboard {
  background: var(--white);
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 24px 64px rgba(0,0,0,.35);
}
.mock-topbar {
  background: var(--primary); padding: 14px 20px;
  display: flex; align-items: center; justify-content: space-between;
}
.mock-nav-items { display: flex; gap: 16px; }
.mock-nav-item { font-size: 12px; font-weight: 600; color: rgba(255,255,255,.6); }
.mock-nav-item.active { color: var(--accent); }
.mock-body { padding: 20px; }
.mock-stat-row { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 12px; margin-bottom: 16px; }
.mock-stat-card {
  background: var(--gray-50); border-radius: 8px; padding: 14px;
  border: 1px solid var(--gray-200);
}
.mock-stat-card .val { font-family: var(--font-heading); font-size: 20px; font-weight: 800; color: var(--primary); }
.mock-stat-card .lbl { font-size: 11px; color: var(--gray-400); }
.mock-course-row { display: flex; flex-direction: column; gap: 8px; }
.mock-course-item {
  display: flex; align-items: center; gap: 12px;
  padding: 10px; background: var(--gray-50);
  border-radius: 8px; border: 1px solid var(--gray-200);
}
.mock-course-thumb {
  width: 36px; height: 36px; border-radius: 6px;
  flex-shrink: 0;
}
.mock-course-info .name { font-size: 12px; font-weight: 600; color: var(--gray-900); }
.mock-course-info .meta { font-size: 11px; color: var(--gray-400); }
.mock-progress { height: 4px; background: var(--gray-200); border-radius: 2px; margin-top: 6px; }
.mock-progress-fill { height: 100%; border-radius: 2px; background: var(--primary); }

/* Student view */
.mock-student { background: var(--white); }
.mock-student-header { background: var(--primary); padding: 16px 20px; }
.mock-student-header h4 { color: var(--white); font-size: 14px; font-weight: 700; }
.mock-student-header p { color: rgba(255,255,255,.6); font-size: 12px; }
.mock-student-body { padding: 16px; }
.mock-enrolled-courses { display: flex; flex-direction: column; gap: 10px; }
.mock-enrolled-item {
  display: flex; align-items: center; gap: 12px;
  padding: 12px; background: var(--gray-50);
  border-radius: 10px;
}
.mock-enrolled-thumb {
  width: 48px; height: 48px; border-radius: 8px;
  flex-shrink: 0;
}
.mock-enrolled-title { font-size: 13px; font-weight: 600; color: var(--gray-900); }
.mock-enrolled-progress-bar { height: 3px; background: var(--gray-200); border-radius: 2px; margin-top: 6px; }
.mock-enrolled-progress-fill { height: 100%; border-radius: 2px; background: #10b981; }
.mock-cert {
  background: linear-gradient(135deg, var(--primary) 0%, #5b3ff0 100%);
  border-radius: 10px; padding: 14px 16px;
  display: flex; align-items: center; gap: 12px; margin-top: 10px;
}
.mock-cert-icon {
  width: 36px; height: 36px; background: var(--accent);
  border-radius: 6px; display: flex; align-items: center; justify-content: center;
  flex-shrink: 0; font-size: 18px;
}
.mock-cert p { font-size: 12px; color: rgba(255,255,255,.75); }
.mock-cert strong { display: block; font-size: 13px; font-weight: 700; color: var(--white); }

/* ─── MEMBERSHIP TIERS ─── */
.tier-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 24px; margin-top: 48px; }
.tier-card {
  background: var(--white);
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-xl);
  padding: 28px;
  transition: all 250ms ease;
}
.tier-card:hover { border-color: var(--primary); box-shadow: var(--shadow-lg); }
.tier-card.featured-tier { border-color: var(--primary); background: var(--primary); }
.tier-card.featured-tier h3,
.tier-card.featured-tier p,
.tier-card.featured-tier .tier-price { color: var(--white); }
.tier-card.featured-tier .tier-period { color: rgba(255,255,255,.5); }
.tier-price { font-family: var(--font-heading); font-size: 36px; font-weight: 800; color: var(--gray-900); }
.tier-period { font-size: 14px; color: var(--gray-400); margin-bottom: 20px; }
.tier-features { list-style: none; display: flex; flex-direction: column; gap: 8px; }
.tier-features li { font-size: 14px; color: var(--gray-600); display: flex; gap: 8px; }
.tier-card.featured-tier .tier-features li { color: rgba(255,255,255,.75); }

/* ─── FILE TYPES ─── */
.file-types-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 16px; margin-top: 48px;
}
.file-type-card {
  background: var(--white); border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 24px 16px; text-align: center;
  transition: all 250ms ease;
}
.file-type-card:hover { border-color: var(--primary); box-shadow: var(--shadow-md); transform: translateY(-3px); }
.file-type-icon {
  width: 48px; height: 48px; border-radius: var(--radius-md);
  margin: 0 auto 12px;
  display: flex; align-items: center; justify-content: center;
}
.file-type-card p { font-size: 14px; font-weight: 600; color: var(--gray-700); }

/* ─── SPOTLIGHT ─── */
.spotlight-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 24px; margin-top: 48px; }
.spotlight-card {
  background: var(--white); border: 1px solid var(--gray-200);
  border-radius: var(--radius-xl); padding: 32px;
  transition: all 250ms ease;
}
.spotlight-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-3px); }
.spotlight-avatar {
  width: 56px; height: 56px; border-radius: 50%;
  background: var(--primary); color: var(--accent);
  display: flex; align-items: center; justify-content: center;
  font-family: var(--font-heading); font-weight: 800; font-size: 20px;
  margin-bottom: 16px;
}
.spotlight-card h4 { font-size: 18px; font-weight: 700; margin-bottom: 4px; }
.spotlight-card .role { font-size: 13px; color: var(--gray-400); margin-bottom: 14px; }
.spotlight-card p { font-size: 15px; color: var(--gray-600); line-height: 1.65; }

/* ─── PRODUCT DEMO ACCORDION ─── */
.demo-section { background: var(--gray-50); }
.demo-accordion {
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-xl);
  overflow: hidden;
  background: var(--white);
  margin-top: 48px;
}
.demo-header {
  padding: 24px 32px;
  display: flex; justify-content: space-between; align-items: center;
  cursor: pointer; background: none; border: none; width: 100%;
  text-align: left; font-family: var(--font-body);
  transition: background var(--transition);
}
.demo-header:hover { background: var(--gray-50); }
.demo-header h3 { font-size: 22px; font-weight: 700; color: var(--gray-900); }
.demo-header p { font-size: 15px; color: var(--gray-500); margin-top: 4px; }
.demo-toggle {
  width: 40px; height: 40px; flex-shrink: 0;
  background: var(--primary);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  transition: transform var(--transition);
}
.demo-toggle svg { color: var(--accent); }
.demo-accordion.open .demo-toggle { transform: rotate(45deg); }
.demo-body {
  max-height: 0; overflow: hidden;
  transition: max-height 400ms ease;
}
.demo-accordion.open .demo-body { max-height: 600px; }
.demo-content {
  padding: 0 32px 32px;
  display: grid; grid-template-columns: 1fr 1fr;
  gap: 32px;
}
.demo-feature { padding: 20px; background: var(--gray-50); border-radius: var(--radius-md); }
.demo-feature h4 { font-size: 16px; font-weight: 700; margin-bottom: 8px; }
.demo-feature p { font-size: 14px; color: var(--gray-500); }

/* ─── VALUE PROPOSITION ─── */
.value-props-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 32px; margin-top: 48px; }
.value-prop-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: 36px 32px;
  border: 1px solid var(--gray-200);
  transition: all 250ms ease;
}
.value-prop-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); border-color: var(--primary); }
.value-prop-num {
  font-family: var(--font-heading);
  font-size: 14px; font-weight: 800;
  color: var(--primary); letter-spacing: .1em;
  margin-bottom: 16px;
}
.value-prop-card h3 { font-size: 22px; font-weight: 700; margin-bottom: 12px; }
.value-prop-card p { font-size: 15px; color: var(--gray-500); line-height: 1.7; }

/* ─── BUSINESS FIT ─── */
.biz-fit-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 48px; align-items: center; margin-top: 48px; }
.biz-fit-visual {
  background: var(--primary);
  border-radius: var(--radius-xl);
  padding: 40px;
  min-height: 360px;
  display: flex; flex-direction: column; justify-content: center;
  position: relative; overflow: hidden;
}
.biz-fit-visual::after {
  content: '';
  position: absolute; bottom: -80px; right: -80px;
  width: 240px; height: 240px;
  background: rgba(230,255,50,.08);
  border-radius: 50%;
}
.biz-fit-stat { color: var(--white); margin-bottom: 24px; }
.biz-fit-stat .big { font-family: var(--font-heading); font-size: 52px; font-weight: 800; color: var(--accent); line-height: 1; }
.biz-fit-stat p { color: rgba(255,255,255,.7); font-size: 15px; margin-top: 4px; }
.biz-fit-features { list-style: none; display: flex; flex-direction: column; gap: 16px; }
.biz-fit-feature {
  display: flex; gap: 14px; align-items: flex-start;
  padding: 16px; background: var(--white);
  border-radius: var(--radius-md); border: 1px solid var(--gray-200);
}

/* ─── RESPONSIVE ─── */
@media (max-width: 1024px) {
  .hero-inner { grid-template-columns: 1fr; gap: 40px; }
  .hero-title { font-size: 36px; }
  .why-content.active { grid-template-columns: 1fr; }
  .ai-grid { grid-template-columns: 1fr; }
  .biz-fit-grid { grid-template-columns: 1fr; }
  .footer-top { grid-template-columns: 1fr 1fr; }
  .demo-content { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-cta { display: none; }
  .nav-hamburger { display: flex; }
  .section { padding: 64px 16px; }
  .section-sm { padding: 40px 16px; }
  .stats-bar-inner { gap: 32px; }
  .testimonial-card { flex: 0 0 85%; }
  .pricing-grid { grid-template-columns: 1fr; max-width: 380px; margin-left: auto; margin-right: auto; }
  .footer-top { grid-template-columns: 1fr 1fr; gap: 32px; }
  .footer-brand { grid-column: 1/-1; }
  .hero-inner { padding-bottom: 40px; }
  .carousel-track { gap: 16px; }
}

@media (max-width: 480px) {
  .stats-bar-inner { flex-direction: column; gap: 24px; }
  .hero-actions { flex-direction: column; }
  .footer-top { grid-template-columns: 1fr; }
  .cta-banner-actions { flex-direction: column; align-items: center; }
  .file-types-grid { grid-template-columns: repeat(3, 1fr); }
}

/* ─── ANIMATIONS ─── */
@keyframes fadeUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}
.fade-up { animation: fadeUp 600ms ease forwards; }
.fade-up-delay-1 { animation-delay: 100ms; opacity: 0; }
.fade-up-delay-2 { animation-delay: 200ms; opacity: 0; }
.fade-up-delay-3 { animation-delay: 300ms; opacity: 0; }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
}

/* ─── UTILS ─── */
.mt-8 { margin-top: 8px; }
.mt-16 { margin-top: 16px; }
.mt-24 { margin-top: 24px; }
.mb-0 { margin-bottom: 0; }
.gap-8 { gap: 8px; }
.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-center { justify-content: center; }
.w-full { width: 100%; }
.rounded-full { border-radius: 100px; }
.bg-accent { background: var(--accent); }
.color-primary { color: var(--primary); }
